CREATE TABLE v6389 AS SELECT x1.v6168 + 1, x1.v6168 + 3072, CAST('2006-09-26' AS DATE) + INTERVAL '1' MONTH, 1 - CAST(POWER(2, 100) AS SIGNED), x1.v6168 - 1, x1.v6168 - 2005, x1.v6168 * 1, x1.v6168 * 2.0, x1.v6168 * 1, 1 / 1, x1.v6168 / 2, x1.v6168 / 1, x1.v6168 + 200, x1.v6168 + 1, CAST('2001-01-01 10:10:10.123456' AS DATETIME) + 1, CAST('10:10:10.123456' AS TIME) - 1, CAST('2001-01-01 10:10:10.123' AS DATETIME) - 1, CAST('2001-01-01 10:10:10.123456' AS DATETIME) - 1, CAST('2001-01-01 10:10:10' AS DATETIME) * 1, CAST('2001-01-01 10:10:10.123' AS DATETIME) * 1, 2 * (3 + 4), CAST('2001-01-01 10:10:10' AS DATETIME) / 1, CAST('2001-01-01 10:10:10.123' AS DATETIME) / 1, x1.v6168 / 2 FROM v6167 AS x1